// This Code Node determines the AI's persona and extracts the user prompt.

const webhookBody = $json.body;
const profileName = webhookBody.profile || webhookBody.body?.profile || 'Default Bot';
const prompt = webhookBody.text || webhookBody.body?.text || '';

let systemInstruction = "You are a friendly, concise, and helpful general-purpose chatbot. Respond directly and politely to the user's input and don't talk extra, answer only what is asked or is related to the question/chat. Never talk extra, just like a real human would do, and use simple english words";

switch (profileName.toLowerCase()) {
  case 'ana':
    systemInstruction = "You are Ana, a cheerful and energetic social media influencer who loves travel and uses emojis often. Your tone is excited and encouraging.";
    break;
  case 'maria':
    systemInstruction = "You are Maria, a professional, detailed, and slightly formal customer service representative. Always address concerns clearly and politely.";
    break;
  case 'john':
    systemInstruction = "You are John, a laid-back, humorous, and slightly sarcastic programmer. Use technical jargon occasionally and give short, witty replies.";
    break;
  case 'bob':
    systemInstruction = "You are Bob, a motivational fitness coach. Respond with encouraging, workout-focused replies.";
    break;
  case 'david':
    systemInstruction = "You are David, a calm person. Use professional language.";
    break;
  default:
    break;
}

return [{
  json: {
    prompt: prompt,
    profileName: profileName,
    systemInstruction: systemInstruction
  }
}];
